// ================================================================
// CONVENIENCE WRAPPER (Recommended)
// ================================================================

/**
 * Predict remaining EV range in kilometers (BASIC - no sensor validation)
 * 
 * @param features Array of 12 sensor values (see feature order above)
 * @return Predicted remaining range in km (e.g., 42.5)
 */
static inline float ev_predict_range_km(const float features[EV_MODEL_N_FEATURES]) {
    return ev_range_model_predict(features, EV_MODEL_N_FEATURES);
}

/**
 * Predict remaining EV range with automatic sensor failure handling (RECOMMENDED)
 * 
 * This is the PRODUCTION-READY version that handles sensor failures gracefully.
 * If sensors return NaN/Inf, they are replaced with training medians.
 * 
 * @param features Array of 12 sensor values (modified in-place if needed)
 * @param out_replaced Optional pointer to store number of sensors replaced (can be NULL)
 * @return Predicted remaining range in km
 */
static inline float ev_predict_range_km_safe(float features[EV_MODEL_N_FEATURES], int* out_replaced) {
    int replaced = ev_safe_impute(features);
    if (out_replaced != NULL) {
        *out_replaced = replaced;
    }
    return ev_range_model_predict(features, EV_MODEL_N_FEATURES);
}

